const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
const rawBodyString = buffer.toString('utf8');
const rawBodyBase64 = buffer.toString('base64');

const item = $input.first().json;
const headers = item.headers || {};

let parsedBody;
try {
  parsedBody = JSON.parse(rawBodyString);
} catch (e) {
  throw new Error('Body no es JSON valido');
}

return [{
  json: {
    rawBodyString,
    rawBodyBase64,
    parsedBody,
    signatureHeader: headers['x-samsara-signature'],
    timestampHeader: headers['x-samsara-timestamp']
  }
}];

const crypto = require('crypto');

const item = $input.first().json;
const { rawBodyString, signatureHeader, timestampHeader } = item;

if (!signatureHeader || !timestampHeader) {
  throw new Error('Faltan headers de firma o timestamp');
}

const secretBuffer = Buffer.from($env.SAMSARA_MOCK_SHARED_SECRET, 'base64');
const signedPayload = `v1:${timestampHeader}:${rawBodyString}`;

const hmac = crypto.createHmac('sha256', secretBuffer);
hmac.update(signedPayload, 'utf8');
const expectedHex = hmac.digest('hex');
const receivedHex = (signatureHeader.split('=')[1] || '').trim();

const expectedBuf = Buffer.from(expectedHex, 'hex');
const receivedBuf = Buffer.from(receivedHex, 'hex');

const signatureValid = expectedBuf.length === receivedBuf.length
  && crypto.timingSafeEqual(expectedBuf, receivedBuf);

if (!signatureValid) {
  throw new Error('Firma invalida');
}

const nowSeconds = Math.floor(Date.now() / 1000);
const tsSeconds = parseInt(timestampHeader, 10);
const toleranceSeconds = 300;

if (!Number.isFinite(tsSeconds) || Math.abs(nowSeconds - tsSeconds) > toleranceSeconds) {
  throw new Error('Timestamp fuera de tolerancia (posible replay)');
}

return [{ json: item }];

const item = $input.first().json;
const { rawBodyString, parsedBody } = item;

const MAX_BODY_BYTES = 10 * 1024;
if (Buffer.byteLength(rawBodyString, 'utf8') > MAX_BODY_BYTES) {
  throw new Error('Body excede el limite de tamano permitido');
}

const isNonEmptyString = (v) => typeof v === 'string' && v.length > 0;
const errors = [];

if (!isNonEmptyString(parsedBody.eventId)) errors.push('eventId invalido');
if (!isNonEmptyString(parsedBody.eventTime)) errors.push('eventTime invalido');
if (!isNonEmptyString(parsedBody.eventType)) errors.push('eventType invalido');

const condition = parsedBody.data && Array.isArray(parsedBody.data.conditions)
  ? parsedBody.data.conditions[0]
  : null;

if (!condition || condition.type !== 'vehicleGeofence') errors.push('tipo de condicion no soportado');
if (!condition || !condition.vehicle || !isNonEmptyString(condition.vehicle.id)) errors.push('vehicle.id invalido');
if (!condition || !condition.geofence || !isNonEmptyString(condition.geofence.id)) errors.push('geofence.id invalido');

if (errors.length > 0) {
  throw new Error(`Esquema invalido: ${errors.join('; ')}`);
}

return [{ json: item }];

