INSERT INTO ops.inbound_events (event_id, event_type, source, payload, status, is_synthetic)
VALUES ($1, $2, 'samsara_mock', convert_from(decode($3, 'base64'), 'UTF8')::jsonb, 'received', true)
ON CONFLICT (event_id) DO NOTHING;

