const parsedBody = $('Parse Raw Body').item.json.parsedBody;
const condition = parsedBody.data.conditions[0];
const vehicle = condition.vehicle;
const geofence = condition.geofence;
const eventType = parsedBody.eventType;
const eventTime = parsedBody.eventTime;

const tripId = vehicle.tripId;
if (tripId === undefined || tripId === null) {
  throw new Error('Evento sin tripId, no se puede procesar');
}

const destinationGeofenceByTrip = {
  7: 'geo-synth-02',
  11: 'geo-synth-01'
};

const isDelivery = eventType === 'GeofenceExit'
  && geofence.id === destinationGeofenceByTrip[tripId];

const PROJECTED_ETA_OFFSET_MIN = 25;
const eventTimeDate = new Date(eventTime);
const projectedEta = new Date(eventTimeDate.getTime() + PROJECTED_ETA_OFFSET_MIN * 60000).toISOString();

return [{
  json: {
    eventId: parsedBody.eventId,
    tripId,
    isDelivery,
    eventTimeIso: eventTime,
    projectedEtaIso: projectedEta
  }
}];

const updateResult = $input.first().json;
const context = $('Compute Trip Update').item.json;

const threshold = parseInt($env.ETA_DEVIATION_ALERT_THRESHOLD_MIN, 10);
const deviation = updateResult.eta_deviation_min;
const shouldNotify = context.isDelivery || Math.abs(deviation) >= threshold;

const message = context.isDelivery
  ? `SINTETICO - Viaje ${updateResult.trip_ref} (ID ${updateResult.trip_id}) ENTREGADO. Desviacion ETA: ${deviation} min.`
  : `SINTETICO - Viaje ${updateResult.trip_ref} (ID ${updateResult.trip_id}) en transito. Desviacion ETA proyectada: ${deviation} min.`;

return [{
  json: {
    ...context,
    etaDeviationMin: deviation,
    tripRef: updateResult.trip_ref,
    shouldNotify,
    notificationMessage: message
  }
}];

